import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Stored names are generated by us ("<32 hex>-<480|960|1600>.webp"), never taken from a user.
 * This one pattern is the only thing that can reach the disk, which rules out path traversal.
 */
const STORED_NAME = /^[a-f0-9]{32}-(480|960|1600)\.webp$/;

export function isSafeStoredName(name: string): boolean {
  return STORED_NAME.test(name);
}

export interface Storage {
  put(name: string, data: Buffer): Promise<void>;
  /** Returns null when the file does not exist. */
  read(name: string): Promise<Buffer | null>;
  remove(name: string): Promise<void>;
}

export function createLocalStorage(root: string): Storage {
  const base = path.resolve(root);

  function locate(name: string): string {
    if (!isSafeStoredName(name)) throw new Error("Unsafe file name");
    const full = path.join(base, name);
    if (path.dirname(full) !== base) throw new Error("Unsafe file name");
    return full;
  }

  return {
    async put(name, data) {
      const target = locate(name);
      await mkdir(base, { recursive: true });
      await writeFile(target, data);
    },
    async read(name) {
      try {
        return await readFile(locate(name));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
    async remove(name) {
      await rm(locate(name), { force: true });
    },
  };
}
